/usr/bin/bash -lc "python - <<'PY'
import urllib.request, io, tarfile
url='https://arxiv.org/src/1903.05032v4'
try:
    data=urllib.request.urlopen(url,timeout=25).read()
    t=tarfile.open(fileobj=io.BytesIO(data), mode='r:*')
    for m in t.getmembers():
        if m.name.endswith('.tex'):
            s=t.extractfile(m).read().decode('utf-8','replace')
            if 'silly_injectivity' in s:
                lines=s.splitlines()
                print('SOURCE:',m.name)
                for i,l in enumerate(lines):
                    if 'silly_injectivity' in l or 'metabelian_injectivity' in l:
                        print('\\nCONTEXT AT',i+1)
                        print('\\n'.join(f'{j+1}: {lines[j]}' for j in range(max(0,i-12),min(len(lines),i+35))))
except Exception as e:
    print(type(e).__name__, str(e))
PY"
